def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    checked_position = 0
    carryon_used = False
    n = len(inputs["lengths"])
    for i in range(n):
        carryon_ok = int(inputs["lengths"][i]) <= 22 and int(inputs["widths"][i]) <= 14 and int(inputs["heights"][i]) <= 9
        is_carryon = carryon_ok and not carryon_used
        if is_carryon:
            carryon_used = True
        else:
            schedule_index = min(checked_position, len(inputs["checked_base_fee_schedule"]) - 1)
            base_fee = int(inputs["checked_base_fee_schedule"][schedule_index])
            dimension_total = int(inputs["lengths"][i]) + int(inputs["widths"][i]) + int(inputs["heights"][i])
            size_fee = 0
            if dimension_total > 62 and dimension_total <= 65:
                size_fee = int(inputs["oversize_fee_schedule"][0])
            if dimension_total > 65:
                size_fee = int(inputs["oversize_fee_schedule"][1])
            weight = int(inputs["weights"][i])
            weight_limit = int(inputs["standard_weight_limit"])
            weight_fee = 0
            if weight > weight_limit and weight <= 53:
                weight_fee = int(inputs["overweight_fee_schedule"][0])
            if weight > 53 and weight <= 70 and weight > weight_limit:
                weight_fee = int(inputs["overweight_fee_schedule"][1])
            if weight > 70:
                weight_fee = int(inputs["overweight_fee_schedule"][2])
            total = total + base_fee + max(size_fee, weight_fee)
            checked_position = checked_position + 1
    return {"answer": int(total)}

def apply(inputs, premises):
    answer = {}
    capacity = float(inputs["limit_per_debtor"])
    if bool(inputs["jointly_owned"]):
        capacity = capacity * int(inputs["debtor_count"])
    n = len(inputs["asset_descriptions"])
    for i in range(n):
        description = str(inputs["asset_descriptions"][i])
        claims = []
        if bool(inputs["eligible_other_personal_property"][i]):
            citation = str(inputs["citation"])
            if bool(inputs["include_claim_values"]):
                claim_value = min(float(inputs["asset_values"][i]), capacity)
                claims = [{"citation": citation, "claim_value": claim_value}]
            else:
                claims = [citation]
        answer[description] = claims
    return {"answer": answer}
